"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 6 (P1 v0.3, section 4): assign recording groups to test, replication, dev and train.

Frozen rule (v0.3): per event class (phone, doorbell, knock) and for decoys in total, the test set needs >= 40 clips
from >= 25 uploaders and the replication set >= 20 clips from >= 12 uploaders; test is filled first, then
replication, and the remaining groups go to train and dev. Groups (same uploader or same sound, from
scripts/step0_fingerprint.py) are atomic. Groups are visited in a seeded random order, so the test groups are a random
sample subject to the minimums; a group joins a split only if it helps a pool that is still short. Groups containing a
test-only clip (the four smoke A Commons recordings) go to test. Remaining groups: dev takes about 20% per pool.

usage: python -I scripts/step0_allocate.py <pools json> <fingerprint json> <output json> [--min name=clips,uploaders ...]
"""
import json
import random
import sys
from collections import defaultdict

POOLS = ["phone", "doorbell", "knock", "decoy"]
DEFAULT_MIN = {"test": (40, 25), "replication": (20, 12)}


def stats(groups, members, pool):
    clips = [c for g in members for c in groups[g]["clips"].get(pool, [])]
    ups = {groups[g]["uploader_of"][c] for g in members for c in groups[g]["clips"].get(pool, [])}
    return len(clips), len(ups)


def allocate(groups, mins, seed=0, door_cell=False, proportional=()):
    order = sorted(groups)
    random.Random(seed).shuffle(order)
    split = {}
    for g in order:
        if groups[g]["test_only"]:
            split[g] = "test"
    if proportional:
        # scarce classes: their groups are split in proportion (test 30%, replication 15%, dev 10%, train 45%)
        # stratified: each group counts for the scarce class it holds most clips of
        for cls in proportional:
            scarce = [g for g in order if g not in split and groups[g]["clips"].get(cls)
                      and max(proportional, key=lambda p: len(groups[g]["clips"].get(p, []))) == cls]
            cut = [round(len(scarce) * f) for f in (0.30, 0.45, 0.55)]
            for i, g in enumerate(scarce):
                split[g] = "test" if i < cut[0] else "replication" if i < cut[1] else "dev" if i < cut[2] else "train"
    if door_cell:
        # doorbell groups are split in proportion (test 25%, replication 15%, dev 10%, train 50% of the groups);
        # the minimums are then checked for the door cell as a whole (doorbell + knock, see main)
        bell = [g for g in order if g not in split and groups[g]["clips"].get("doorbell")]
        cut = [round(len(bell) * f) for f in (0.25, 0.40, 0.50)]
        for i, g in enumerate(bell):
            split[g] = "test" if i < cut[0] else "replication" if i < cut[1] else "dev" if i < cut[2] else "train"
    for name in ("test", "replication"):
        for g in order:
            if g in split:
                continue
            members = [x for x, s in split.items() if s == name]
            short = [p for p in POOLS
                     if any(a < b for a, b in zip(stats(groups, members, p), mins[name].get(p, mins[name]["*"])))]
            if not short:
                break
            if any(groups[g]["clips"].get(p) for p in short):
                split[g] = name
    rest = [g for g in order if g not in split]
    dev_count = defaultdict(int)
    for g in rest:
        main = max(groups[g]["clips"], key=lambda p: len(groups[g]["clips"][p]))
        dev_count[main] += 1
        split[g] = "dev" if dev_count[main] % 5 == 0 else "train"
    return split


def main(pools_path, fp_path, out_path, *overrides):
    pools = json.load(open(pools_path, encoding="utf-8"))["clips"]
    fp = json.load(open(fp_path, encoding="utf-8"))
    group_of = fp["group_of"]
    excluded = set()
    for o in overrides:                                 # --exclude=<json with "excluded_clips"> (e.g. MUSAN matches)
        if o.startswith("--exclude="):
            excluded |= set(json.load(open(o.split("=", 1)[1], encoding="utf-8"))["excluded_clips"])
    groups = defaultdict(lambda: {"clips": defaultdict(list), "uploader_of": {}, "test_only": False})
    for name, gid in group_of.items():
        if name in excluded:
            continue
        if name in pools and pools[name]["pool"] in POOLS:
            groups[gid]["clips"][pools[name]["pool"]].append(name)
            groups[gid]["uploader_of"][name] = pools[name]["uploader"]
        elif not name.isdigit():                       # an extra (test-only) clip, e.g. a Commons recording
            groups[gid]["test_only"] = True
    groups = {g: v for g, v in groups.items() if v["clips"]}
    mins = {k: {"*": v} for k, v in DEFAULT_MIN.items()}
    door_cell = "--door-cell" in overrides
    for o in overrides:                                 # e.g. test:doorbell=40,15
        if o.startswith("--"):
            continue
        key, val = o.split("=")
        name, pool = key.split(":")
        mins[name][pool] = tuple(int(x) for x in val.split(","))
    if door_cell:
        # the knock + doorbell minimum is checked on the knock pool after crediting the doorbell groups already placed
        for name in ("test", "replication"):
            mins[name]["doorbell"] = (0, 0)
    proportional = tuple(o.split("=", 1)[1].split(",") for o in overrides if o.startswith("--proportional="))
    proportional = proportional[0] if proportional else ()
    for name in ("test", "replication"):
        for p in proportional:
            mins[name][p] = (0, 0)
    split = allocate(groups, mins, door_cell=door_cell, proportional=proportional)
    if door_cell:
        for name in ("test", "replication"):
            members = [g for g, s in split.items() if s == name]
            b, k = stats(groups, members, "doorbell"), stats(groups, members, "knock")
            print(f"door cell {name}: doorbell {b[0]} clips / {b[1]} upl + knock {k[0]} / {k[1]} "
                  f"= {b[0] + k[0]} clips / {b[1] + k[1]} uploaders")
    report = {"minimums": {k: {p: list(v) for p, v in d.items()} for k, d in mins.items()}, "table": {}}
    print(f"{'pool':9s} " + " ".join(f"{s:>22s}" for s in ("test", "replication", "dev", "train")))
    for p in POOLS:
        row = {}
        for s in ("test", "replication", "dev", "train"):
            members = [g for g, x in split.items() if x == s]
            n, u = stats(groups, members, p)
            row[s] = {"clips": n, "uploaders": u, "groups": sum(1 for g in members if groups[g]["clips"].get(p))}
        report["table"][p] = row
        print(f"{p:9s} " + " ".join(f"{row[s]['clips']:5d} clips {row[s]['uploaders']:3d} upl {row[s]['groups']:3d} gr"
                                     for s in ("test", "replication", "dev", "train")))
    report["split_of_group"] = split
    report["excluded_clips"] = sorted(excluded)
    # per-clip manifest; unseen-type clips (report-only) go to test or replication by group (2:1), unless their group
    # also holds a pool clip (then they are not unseen) or they were excluded; Commons clips are test-only
    manifest, unseen_groups = {}, sorted({group_of[n] for n, v in pools.items()
                                          if v["pool"].startswith("unseen_") and n not in excluded})
    pool_groups = {group_of[n] for n, v in pools.items() if v["pool"] in POOLS and n not in excluded}
    rng = random.Random(1)
    rng.shuffle(unseen_groups)
    unseen_split = {g: ("test" if i % 3 < 2 else "replication") for i, g in enumerate(unseen_groups)}
    for name, gid in group_of.items():
        if name in excluded:
            manifest[name] = {"split": "excluded", "group": gid, "reason": "matches a MUSAN noise file"}
        elif name in pools and pools[name]["pool"] in POOLS:
            manifest[name] = {"split": split[gid], "group": gid, "pool": pools[name]["pool"]}
        elif name in pools:                              # unseen event types
            ok = gid not in pool_groups
            manifest[name] = {"split": unseen_split[gid] if ok else "excluded", "group": gid,
                              "pool": pools[name]["pool"], **({} if ok else {"reason": "same group as a pool clip"})}
        else:
            manifest[name] = {"split": "test", "group": gid, "pool": "commons_test_only"}
    report["manifest"] = manifest
    from collections import Counter
    print("unseen subsets:", dict(Counter((v["pool"], v["split"]) for v in manifest.values()
                                          if v.get("pool", "").startswith("unseen_"))))
    json.dump(report, open(out_path, "w", encoding="utf-8"), indent=1)


if __name__ == "__main__":
    main(*sys.argv[1:])
